  // "don't", which leaves editing here as the only idea they have. Under Atomaton
  // the build steps are commands in config.yaml -- a file they own, that an agent
  // can write, and that survives an upgrade -- so the header names it.
  headerText: [
    "# AUTO-GENERATED by Atomaton -- DO NOT EDIT DIRECTLY.",
    "# Generated from: <source-file-path>",
    "# Edits here are lost when this file is regenerated upstream.",
    "#",
    "# To change what CI or deployment DOES, you do not need this file: put the",
