71	  // before the rename and survived the audit as a name with no writer. And `"main"`
72	  // was a guess standing in for a value this repository already holds -- on a project
73	  // whose base is `develop`, every dispatched scan computed its range against a branch
74	  // the work does not come from, and either found nothing or scanned the wrong commits.
75	  const base = baseBranch();
76	  if (!base) {
